using System;
using NetTopologySuite.Geometries;
using NetTopologySuite.Index.Strtree;

var tree = new STRtree<int>();
tree.Insert(new Envelope(0, 0, 0, 0), 0);
tree.Insert(new Envelope(1, 1, 1, 1), 1);
tree.Build();
var root = tree.Root;
if (root.ChildBoundables.Count != 2) throw new Exception("Unexpected child count");
foreach (var child in root.ChildBoundables) {
    Envelope bounds = child.Bounds;
    if (bounds.IsNull) throw new Exception("Missing bounds");
}
Console.WriteLine("NTS 2.6.0 STRtree: public Root, ChildBoundables and Bounds compile and run; 2 procedural items checked.");
